<?php
require __DIR__.'/_init.php';require_login();$errors=[];$q=db()->prepare('SELECT full_name,username,email,student_number FROM users WHERE id=?');$q->execute([$_SESSION['user']['id']]);$profile=$q->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$student=trim($_POST['student_number']??'');$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';if(mb_strlen($name)<2||mb_strlen($name)>120)$errors[]='Enter a name between 2 and 120 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if($student==='')$errors[]='Student number is required.';if($new!==''&&(strlen($new)<12||strlen($new)>72))$errors[]='New password must be 12–72 bytes.';if($new!==''&&$current==='')$errors[]='Enter your current password to change it.';if(!$errors){try{if($new!==''){$s=db()->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute([$_SESSION['user']['id']]);if(!password_verify($current,(string)$s->fetchColumn()))$errors[]='Current password is incorrect.';else{$s=db()->prepare('UPDATE users SET full_name=?,email=?,student_number=?,password_hash=? WHERE id=?');$s->execute([$name,$email,$student,password_hash($new,PASSWORD_DEFAULT),$_SESSION['user']['id']]);}}else{$s=db()->prepare('UPDATE users SET full_name=?,email=?,student_number=? WHERE id=?');$s->execute([$name,$email,$student,$_SESSION['user']['id']]);}if(!$errors){$_SESSION['user']['full_name']=$name;$_SESSION['user']['email']=$email;$q=db()->prepare('SELECT full_name,username,email,student_number FROM users WHERE id=?');$q->execute([$_SESSION['user']['id']]);$profile=$q->fetch();flash('Profile updated.');header('Location: /profile.php');exit;}}catch(PDOException $ex){$errors[]=$ex->getCode()==='23000'?'That email or student number is already in use.':'Profile could not be updated.';}}}
page_start('My profile');?><section class="form-wrap wide"><div class="eyebrow">ACCOUNT SETTINGS</div><h1>My profile</h1><?php foreach($errors as $x)echo '<p class="error">'.e($x).'</p>';?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Full name<input name="full_name" maxlength="120" value="<?=e($profile['full_name'])?>" required></label><label>Username<input value="<?=e($profile['username'])?>" disabled></label><label>Email<input type="email" name="email" value="<?=e($_POST['email']??$profile['email'])?>" required></label><label>Student number<input name="student_number" value="<?=e($_POST['student_number']??$profile['student_number'])?>" required></label><hr><h2>Change password</h2><label>Current password<input type="password" name="current_password" autocomplete="current-password"></label><label>New password (leave blank to keep current)<input type="password" name="new_password" minlength="12" maxlength="72" autocomplete="new-password"></label><button class="button">Save profile</button></form></section><?php page_end();?>
